python3 << 'PY'
import pandas as pd
import numpy as np
import scipy.stats as stats

stations = pd.read_csv('/app/dataset/stations.csv')
readings = pd.read_csv('/app/dataset/readings.csv')
pm25 = readings[readings['pollutant']=='PM25']
pm25_pivot = pm25.pivot_table(index='timestamp', columns='station_id', values='current_reading').sort_index()
st_info = stations.set_index('station_id')

def max_lag_corr(target, district, maxlag=3):
    peers = st_info[st_info['district']==district].index.intersection(pm25_pivot.columns)
    # exclude target if we want peer reference
    peers_ref = [p for p in peers if p != target]
    if len(peers_ref) == 0:
        return None
    ref = pm25_pivot[peers_ref].median(axis=1, skipna=True)
    t = pm25_pivot[target]
    best = (-10, -1)
    for lag in range(-maxlag, maxlag+1):
        if lag < 0:
            a = t.iloc[:lag]; b = ref.iloc[-lag:]
        elif lag == 0:
            a = t; b = ref
        else:
            a = t.iloc[lag:]; b = ref.iloc[:-lag]
        if len(a) > 5 and len(b) > 5:
            try:
                r = stats.pearsonr(a, b)[0]
            except:
                continue
            if r > best[1]:
                best = (lag, r)
    return best

# Try on a few examples
for target in ['ST001', 'ST002', 'ST003', 'ST010', 'ST011']:
    d = st_info.loc[target, 'district']
    res = max_lag_corr(target, d)
    if res:
        print(f'{target} ({d}): best_lag={res[0]}, r={res[1]:.3f}, lag0_r={stats.pearsonr(pm25_pivot[target], pm25_pivot[[p for p in st_info[st_info["district"]==d].index if p in pm25_pivot.columns and p!=target]].median(axis=1, skipna=True))[0]:.3f}')
